        return False, f"File not found: {filepath}"
    try:
        with open(filepath, "r", encoding="utf-8") as f:
            reader = csv.DictReader(f)
            seen = set()
            for row in reader:
                val = row.get(column_name, "").strip()
                if val in seen:
                    return False, f"Duplicate values found in column '{column_name}' in {filepath}: {val}"
                seen.add(val)
            return True, f"No duplicates in column '{column_name}' in {filepath}"
    except Exception as e:
        return False, f"Error checking uniqueness in {filepath}: {e}"


