def check_file_exists(filepath):
    """Check if a file exists."""
    return os.path.isfile(filepath)


def check_file_not_empty(filepath):
    """Check if a file exists and is not empty."""
    if not check_file_exists(filepath):
        return False, f"File not found: {filepath}"
    return os.path.getsize(filepath) > 0, f"File is empty: {filepath}" if os.path.getsize(filepath) == 0 else f"File is not empty: {filepath}"


def check_csv_has_columns(filepath, expected_columns):
    """Check that a CSV file has the expected columns."""
    if not check_file_exists(filepath):
        return False, f"File not found: {filepath}"
    try:
        with open(filepath, "r", encoding="utf-8") as f:
            reader = csv.reader(f)
            headers = next(reader, None)
            if headers is None:
                return False, f"CSV has no headers: {filepath}"
            headers = [h.strip() for h in headers]
            missing = [c for c in expected_columns if c not in headers]
            if missing:
                return False, f"Missing columns in {filepath}: {missing}"
            return True, f"All expected columns present in {filepath}"
    except Exception as e:
        return False, f"Error reading columns from {filepath}: {e}"


def check_csv_row_count(filepath, min_rows=1):
    """Check that a CSV file has at least min_rows data rows."""
    if not check_file_exists(filepath):
        return False, f"File not found: {filepath}"
    try:
        with open(filepath, "r", encoding="utf-8") as f:
            reader = csv.reader(f)
            next(reader, None)  # skip header
            count = sum(1 for _ in reader)
            if count < min_rows:
                return False, f"Expected at least {min_rows} rows in {filepath}, found {count}"
            return True, f"Row count in {filepath}: {count}"
    except Exception as e:
        return False, f"Error counting rows in {filepath}: {e}"


def check_csv_has_numeric_column(filepath, column_name):
    """Check that a specific column contains valid numeric values."""
    if not check_file_exists(filepath):
        return False, f"File not found: {filepath}"
    try:
        with open(filepath, "r", encoding="utf-8") as f:
            reader = csv.DictReader(f)
            for row in reader:
                val = row.get(column_name, "").strip()
                if val == "":
                    continue
                float(val)  # will raise ValueError if not numeric
            return True, f"Column '{column_name}' in {filepath} contains valid numeric values"
    except Exception as e:
        return False, f"Error validating column '{column_name}' in {filepath}: {e}"


def check_csv_unique_column(filepath, column_name):
    """Check that a specific column has no duplicate values."""
    if not check_file_exists(filepath):
        return False, f"File not found: {filepath}"
    try:
        with open(filepath, "r", encoding="utf-8") as f:
            reader = csv.DictReader(f)
            seen = set()
            for row in reader:
                val = row.get(column_name, "").strip()
                if val in seen:
                    return False, f"Duplicate values found in column '{column_name}' in {filepath}: {val}"
                seen.add(val)
            return True, f"No duplicates in column '{column_name}' in {filepath}"
    except Exception as e:
        return False, f"Error checking uniqueness in {filepath}: {e}"


def check_csv_range(filepath, column_name, min_val, max_val):
    """Check that a numeric column falls within a given range."""
    if not check_file_exists(filepath):
        return False, f"File not found: {filepath}"
    try:
        with open(filepath, "r", encoding="utf-8") as f:
            reader = csv.DictReader(f)
            for row in reader:
                val_str = row.get(column_name, "").strip()
                if val_str == "":
                    continue
                val = float(val_str)
                if val < min_val or val > max_val:
                    return False, f"Value {val} out of range [{min_val}, {max_val}] in column '{column_name}' in {filepath}"
            return True, f"All values in '{column_name}' in {filepath} within [{min_val}, {max_val}]"
    except Exception as e:
        return False, f"Error checking range in {filepath}: {e}"


